export const stories = [...globalStories, ...indianStories];

export function getStoryBySlug(slug) {
  return stories.find((s) => s.slug === slug);
}

export function getRelatedStories(story, limit = 4) {
  if (!story) return [];
  const bySlug = new Map(stories.map((s) => [s.slug, s]));
  const explicit = (story.relatedSlugs || [])
    .map((slug) => bySlug.get(slug))
    .filter(Boolean);
  if (explicit.length >= limit) return explicit.slice(0, limit);

  // Fallback: overlap on themes/badges.
  const themes = new Set(story.themes || []);
  const badges = new Set(story.badges || []);
  const scored = stories
    .filter((s) => s.slug !== story.slug && !explicit.some((e) => e.slug === s.slug))
    .map((s) => {
      const themeMatch = (s.themes || []).filter((t) => themes.has(t)).length;
      const badgeMatch = (s.badges || []).filter((b) => badges.has(b)).length;
      return { s, score: themeMatch * 2 + badgeMatch };
    })
    .sort((a, b) => b.score - a.score);

  return [...explicit, ...scored.slice(0, limit - explicit.length).map((x) => x.s)];
}

export function smartSearch(query) {
  const q = (query || '').trim().toLowerCase();
  if (!q) return stories;
  return stories.filter((s) => {
    const haystack = [
      s.name, s.product, s.founders, s.hook, s.metrics?.industry, s.metrics?.hq,
      ...(s.badges || []), ...(s.themes || []),
      s.sections?.problem, s.sections?.spark, s.openingScene,
    ]
      .filter(Boolean)
      .join(' \u00b7 ')
      .toLowerCase();
    return haystack.includes(q);
  });
}
